document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("rebar-form"),n=document.getElementById("rebar-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("rebar-length").value),r=parseFloat(document.getElementById("rebar-width").value),[s,i,a]=document.getElementById("rebar-size").value.split(",").map(Number),p=parseFloat(document.getElementById("rebar-spacing").value),o=document.getElementById("rebar-project").value;if(t<=0||r<=0)return n.textContent="Please enter valid dimensions.",void 0;const l=12*t,c=12*r;let d,u,h;switch(o){case"slab":case"driveway":d=Math.floor(c/p)+1,u=Math.floor(l/p)+1,h=d+u;break;case"footing":d=Math.floor(c/p)+1,u=0,h=d;break;case"wall":const e=8;d=Math.floor(l/p)+1,u=Math.floor(12*e/p)+1,h=d+u;break;default:d=u=h=0}const g=d*t+u*r,m=1.1*g,v=Math.ceil(m/20),f=v*a,b=d*u,$=Math.ceil(1.1*b),y=Math.ceil(g/4),w=.05*$+2*y,k=f+w,P=m*{3:.376,4:.668,5:1.043,6:1.502,7:2.044}[s];let M="";switch(o){case"slab":case"driveway":M='3" from bottom, 2" from top';break;case"footing":M='3" from all sides';break;case"wall":M='2" exterior, 3/4" interior'}n.innerHTML=`\n        <div class="result-section">\n          <h4>Project Specifications:</h4>\n          <p>Dimensions: ${t}' × ${r}'</p>\n          <p>Rebar size: #${s} (${i}")</p>\n          <p>Spacing: ${p}" on center</p>\n          <p>Project type: ${o.charAt(0).toUpperCase()+o.slice(1)}</p>\n        </div>\n        \n        <div class="result-layout">\n          <h4>Rebar Layout:</h4>\n          ${"slab"===o||"driveway"===o?`\n          <p><strong>Lengthwise bars:</strong> ${d} pieces @ ${t}' each</p>\n          <p><strong>Widthwise bars:</strong> ${u} pieces @ ${r}' each</p>\n          <p>Grid intersections: ${b}</p>\n          `:"footing"===o?`\n          <p><strong>Parallel bars:</strong> ${d} pieces @ ${t}' each</p>\n          `:`\n          <p><strong>Horizontal bars:</strong> ${d} pieces @ ${t}' each</p>\n          <p><strong>Vertical bars:</strong> ${u} pieces @ 8' each</p>\n          `}\n          <p><strong>Total bars needed: ${h}</strong></p>\n        </div>\n        \n        <div class="result-materials">\n          <h4>Material Requirements:</h4>\n          <p>Linear feet: ${g.toFixed(1)} ft</p>\n          <p>With waste (10%): ${m.toFixed(1)} ft</p>\n          <p><strong>20-foot sticks: ${v}</strong></p>\n          <p>Total weight: ${P.toFixed(0)} lbs</p>\n          <p>Rebar cost: $${f.toFixed(0)}</p>\n        </div>\n        \n        <div class="result-accessories">\n          <h4>Installation Accessories:</h4>\n          <p>Tie wires needed: ${$}</p>\n          <p>Rebar chairs: ${y}</p>\n          <p>Accessory cost: $${w.toFixed(0)}</p>\n          <p><strong>Total project cost: $${k.toFixed(0)}</strong></p>\n        </div>\n        \n        <div class="result-placement">\n          <h4>Placement Guidelines:</h4>\n          <p>Concrete cover: ${M}</p>\n          <p>Lap splices: ${12*s}" minimum (${s} × diameter × 12)</p>\n          <p>Bend radius: ${3*s}" minimum</p>\n          <p>Support spacing: Every 4-5 feet</p>\n        </div>\n        \n        <div class="result-installation">\n          <h4>Installation Steps:</h4>\n          <p>1. Place chairs/supports at proper spacing</p>\n          <p>2. Lay lengthwise bars first</p>\n          <p>3. Place widthwise bars on top</p>\n          <p>4. Secure intersections with tie wire</p>\n          <p>5. Check cover distances</p>\n          <p>6. Pour concrete within 24 hours</p>\n        </div>\n        \n        <div class="result-strength">\n          <h4>Reinforcement Benefits:</h4>\n          <p>✅ Prevents cracking from temperature changes</p>\n          <p>✅ Increases load-bearing capacity</p>\n          <p>✅ Improves durability and lifespan</p>\n          <p>✅ Required for most commercial applications</p>\n          <p>✅ Provides structural integrity</p>\n        </div>\n        \n        <div class="result-tools">\n          <h4>Tools Required:</h4>\n          <p>🔧 Rebar cutter or angle grinder</p>\n          <p>🪝 Rebar bender (for smaller sizes)</p>\n          <p>✂️ Tie wire twisters</p>\n          <p>📏 Measuring tape</p>\n          <p>🧤 Work gloves (cut-resistant)</p>\n          <p>👀 Safety glasses</p>\n        </div>\n        \n        <div class="result-delivery">\n          <h4>Delivery & Handling:</h4>\n          <p>Delivery weight: ${P.toFixed(0)} lbs</p>\n          <p>Transport: ${P>1e3?"Truck delivery recommended":"Can fit in pickup truck"}</p>\n          <p>Storage: Keep dry, off ground</p>\n          <p>Handling: Use proper lifting techniques</p>\n        </div>\n        \n        <div class="result-tips">\n          <h4>Professional Tips:</h4>\n          <p>📐 Plan layout to minimize cutting and waste</p>\n          <p>🔗 Stagger lap joints for strength</p>\n          <p>📏 Double-check spacing before concrete pour</p>\n          <p>⏰ Complete pour within 24 hours of placement</p>\n          <p>🌦️ Protect from weather during installation</p>\n        </div>\n      `})});